def findConcatenationStarts(s, words, wordLen):
    L = wordLen
    m = len(words) // L
    total = m * L
    n = len(s)
    res = []
    if total > n:
        return res
    need = {}
    for i in range(0, len(words), L):
        w = words[i:i + L]
        need[w] = need.get(w, 0) + 1
    for off in range(L):
        have = {}
        count = 0
        left = off
        for right in range(off, n - L + 1, L):
            w = s[right:right + L]
            if w in need:
                have[w] = have.get(w, 0) + 1
                count += 1
                while have[w] > need[w]:
                    have[s[left:left + L]] -= 1
                    left += L
                    count -= 1
                if count == m:
                    res.append(left)
                    have[s[left:left + L]] -= 1
                    left += L
                    count -= 1
            else:
                have.clear()
                count = 0
                left = right + L
    res.sort()
    return res
